package org.systemmaster.continuity;
import java.time.Instant; import java.util.*;
public final class ResumeAuthorities{private ResumeAuthorities(){}
 public enum Decision{ALLOW,DENY,UNKNOWN}
 public record RecoveryStanding(String recoveryId,String workUnitId,long recoveryEpoch,long version,String state){public RecoveryStanding{recoveryId=RecordedDecision.req(recoveryId,"recoveryId");workUnitId=RecordedDecision.req(workUnitId,"workUnitId");if(recoveryEpoch<1||version<1)throw new IllegalArgumentException();state=RecordedDecision.req(state,"state");}}
 public interface RecoveryStandingAuthority{RecoveryStanding current(String recoveryId);} public interface PlanAuthority{RecoveryPlan currentPlan(String recoveryId);} public interface FenceAuthority{void assertClaim(String recoveryId,String claimId,long fenceEpoch);void assertFence(String recoveryId,long fenceEpoch);} public interface CompatibilityAuthority{Decision allowed(RecoveryPlan plan);} public interface ReconciliationAuthority{Decision complete(RecoveryPlan plan);} public interface ResourceAdmissionAuthority{Decision admitted(String recoveryId,String resourceClass);} public interface RuntimeIdentityAuthority{String runtimeIdentity(RecoveryPlan plan);} public interface AttemptClock{Instant now();}
 public interface RecoveryTransitionAuthority{void resumeStarted(String recoveryId,long expectedVersion,String attemptId);void verificationPending(String recoveryId,String attemptId);void recoveryFailed(String recoveryId,String attemptId,String evidenceDigest);void markRecovered(String recoveryId,String attemptId,List<String> evidenceRefs);} public interface VerificationAuthority{Decision verify(String recoveryId,String attemptId,List<String> evidenceRefs);boolean unresolvedCriticalEffects(String recoveryId);}
}
